import{_ as t,c as l,o as r,ah as a}from"./chunks/framework.PvdZnrZd.js";const h=JSON.parse('{"title":"Order Fulfillment","description":"Order Fulfillment","frontmatter":{"title":"Order Fulfillment","description":"Order Fulfillment","author":"Chirag Tyagi"},"headers":[],"relativePath":"zenith/order/partial-fulfillment.md","filePath":"zenith/order/partial-fulfillment.md"}'),o={name:"zenith/order/partial-fulfillment.md"};function i(n,e,p,s,d,f){return r(),l("div",null,[...e[0]||(e[0]=[a('<p>Till now, <a href="/zenith/introduction/">Multi-Vendor Marketplace App</a> facilitates admin as well as the seller to <a href="/zenith/order/order-fulfillment.html">fulfill orders</a> from their respective panels. Now, we have introduced a <strong>partial fulfillment</strong> feature as well.</p><p>You can fulfill a part of an order by fulfilling some line items. Let&#39;s learn how you can activate this feature within the marketplace app.</p><h2 id="enable-partial-fulfillment" tabindex="-1">Enable Partial Fulfillment <a class="header-anchor" href="#enable-partial-fulfillment" aria-label="Permalink to &quot;Enable Partial Fulfillment&quot;">​</a></h2><p>Visit <strong>Multivendor Admin Panel</strong> &gt; <strong>Configuration</strong> &gt; <strong>Order Configuration</strong></p><p><strong>NOTE: Once you enable the partial fulfillment option, you can’t disable it further!</strong></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/02/download-1-1-1200x567.png" alt="Enable Partial Fulfillment"></p><h2 id="steps-to-partially-fulfill-the-orders" tabindex="-1">Steps to Partially Fulfill the Orders <a class="header-anchor" href="#steps-to-partially-fulfill-the-orders" aria-label="Permalink to &quot;Steps to Partially Fulfill the Orders&quot;">​</a></h2><p>The seller needs to visit <strong>MVM Seller Panel</strong> &gt; <strong>Orders</strong> &gt; <strong>Order Listing</strong>&gt; <strong>View</strong> the order you want to fulfill &gt; <strong>Accept</strong> the order and then proceed to fulfill:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/02/image-2-1200x597.png" alt="Proceed to partial fulfill order"></p><p>Next, enter the quantity of products you want to fulfill and proceed.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/02/image-3-1200x597.png" alt="image-3"></p><p>Further, enter the fulfillment method, enter the tracking details if needed and fulfill.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/02/image-4-1200x542.png" alt="image-4"></p><p>On the order page, you will have the fulfilled &amp; unfilled products listed:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2021/02/image-5-1200x886.png" alt="image-5"></p><p>Drop your query/suggestion at <a href="mailto:support@webkul.com" target="_blank" rel="noreferrer">support@webkul.com</a> or create your ticket at <a href="https://webkul.uvdesk.com/" target="_blank" rel="noreferrer">Webkul UV Desk</a>.</p><h2 id="read-more-order-fulfillment-in-multivendor-marketplace-for-shopify" tabindex="-1">Read more: Order fulfillment in Multivendor Marketplace for Shopify <a class="header-anchor" href="#read-more-order-fulfillment-in-multivendor-marketplace-for-shopify" aria-label="Permalink to &quot;Read more: Order fulfillment in Multivendor Marketplace for Shopify&quot;">​</a></h2><p>In <a href="/zenith/introduction/">Multi-Vendor Marketplace</a>, once the order is being placed from the Shopify store then each seller can do the fulfillment of their respective products directly from their seller panel on the app.</p><p>But, we do give the Admin an option to restrict his Sellers from fulfilling the orders.</p><p>In other words, if the admin doesn’t want his sellers to fulfill the orders &amp; instead he wants to fulfill the order then he can do so in the Multivendor Marketplace.</p><p>Check the two cases in depth by visiting this <a href="/zenith/order/order-fulfillment.html">link</a>.</p>',21)])])}const c=t(o,[["render",i]]);export{h as __pageData,c as default};
